  describe("changeProjectLead", () => {
    async function leadOf(orgId: OrgId, projectId: ProjectId): Promise<UserId | null | undefined> {
      return (await projectRepo.findProjectById(orgId, projectId))?.leadId;
    }

    it("lets an admin hand the project to an active member", async () => {
      const tenant = await createTenant("leadadmin", "growth");

      const changed = await projectService.changeProjectLead(tenant.actors.admin, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        leadId: tenant.userIds.member,
      });

      expect(changed.leadId).toBe(tenant.userIds.member);
      expect(await leadOf(tenant.org.id, tenant.project.id)).toBe(tenant.userIds.member);
    });

    it("clears the lead when leadId is null", async () => {
      const tenant = await createTenant("leadclear", "growth");

      const changed = await projectService.changeProjectLead(tenant.actors.owner, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        leadId: null,
      });

      expect(changed.leadId).toBeNull();
      expect(await leadOf(tenant.org.id, tenant.project.id)).toBeNull();
    });

    it("lets the current lead hand the project on whatever their role", async () => {
      const tenant = await createTenant("leadhandover", "growth");

      await projectService.changeProjectLead(tenant.actors.owner, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        leadId: tenant.userIds.member,
      });
      await projectService.changeProjectLead(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        leadId: tenant.userIds.admin,
      });

      expect(await leadOf(tenant.org.id, tenant.project.id)).toBe(tenant.userIds.admin);
    });

    it("refuses a caller who is neither an admin nor the lead", async () => {
      const tenant = await createTenant("leaddeny", "growth");

      for (const actor of [tenant.actors.member, tenant.actors.viewer]) {
        await expect(
          projectService.changeProjectLead(actor, {
            orgId: tenant.org.id,
            projectId: tenant.project.id,
            leadId: tenant.userIds.admin,
          }),
        ).rejects.toThrow(PermissionDeniedError);
      }

      expect(await leadOf(tenant.org.id, tenant.project.id)).toBe(tenant.userIds.owner);
    });

    it("refuses an org id other than the actor's", async () => {
      const tenant = await createTenant("leadscopea", "growth");
      const other = await createTenant("leadscopeb", "growth");

      await expect(
        projectService.changeProjectLead(tenant.actors.owner, {
          orgId: other.org.id,
          projectId: other.project.id,
          leadId: null,
        }),
      ).rejects.toThrow(TenantScopeError);
      expect(await leadOf(other.org.id, other.project.id)).toBe(other.userIds.owner);
    });

    it("reports another organization's project id as not found", async () => {
      const tenant = await createTenant("leadxproja", "growth");
      const other = await createTenant("leadxprojb", "growth");

      await expect(
        projectService.changeProjectLead(tenant.actors.owner, {
          orgId: tenant.org.id,
          projectId: other.project.id,
          leadId: null,
        }),
      ).rejects.toThrow(NotFoundError);
      expect(await leadOf(other.org.id, other.project.id)).toBe(other.userIds.owner);
    });

    it("refuses to change the lead of an archived project", async () => {
      const tenant = await createTenant("leadarchived", "growth");
      await projectService.archiveProject(tenant.actors.admin, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        archiveIssues: false,
      });

      await expect(
        projectService.changeProjectLead(tenant.actors.admin, {
          orgId: tenant.org.id,
          projectId: tenant.project.id,
          leadId: tenant.userIds.member,
        }),
      ).rejects.toThrow(AlreadyArchivedError);
      expect(await leadOf(tenant.org.id, tenant.project.id)).toBe(tenant.userIds.owner);
    });

    it("rejects a lead who never joined, belongs elsewhere, or was removed", async () => {
      const tenant = await createTenant("leadnonmember", "growth");
      const elsewhere = await createTenant("leadelsewhere", "growth");
      const stranger = await userRepo.insertUser({
        email: "stranger@leadnonmember.test",
        name: "Stranger",
        passwordHash: "seed",
      });
      const departed = await userRepo.insertUser({
        email: "departed@leadnonmember.test",
        name: "Departed",
        passwordHash: "seed",
      });
      const departedMember = await memberRepo.insertMember(
        tenant.org.id,
        departed.id,
        "member",
        null,
      );
      await memberRepo.archiveMember(tenant.org.id, departedMember.id);

      for (const leadId of [stranger.id, elsewhere.userIds.member, departed.id]) {
        await expect(
          projectService.changeProjectLead(tenant.actors.admin, {
            orgId: tenant.org.id,
            projectId: tenant.project.id,
            leadId,
          }),
        ).rejects.toThrow(NotFoundError);
      }
      expect(await leadOf(tenant.org.id, tenant.project.id)).toBe(tenant.userIds.owner);
    });

    it("rejects a new lead who could not update the project themselves", async () => {
      const tenant = await createTenant("leadviewer", "growth");

      await expect(
        projectService.changeProjectLead(tenant.actors.owner, {
          orgId: tenant.org.id,
          projectId: tenant.project.id,
          leadId: tenant.userIds.viewer,
        }),
      ).rejects.toThrow(PermissionDeniedError);
      expect(await leadOf(tenant.org.id, tenant.project.id)).toBe(tenant.userIds.owner);
    });
  });
});

